#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6
umask 077
mkdir -p .private
ENV_FILE=.private/hosting-owner.env
export GH_REPO=jtoosh/baseball-mcp
set +x

# Input goes to Vercel over stdin; it never appears in command arguments.
put_vercel() {
  local name="$1" value="$2" target="$3" kind="$4"
  [[ -n "$value" ]] || { warn "$name must not be empty"; exit 1; }
  if ! printf '%s' "$value" | npx --yes vercel@63.1.2 env add "$name" "$target" --type "$kind" --project baseball-mcp >/dev/null 2>&1; then
    if ! printf '%s' "$value" | npx --yes vercel@63.1.2 env update "$name" "$target" --type "$kind" --project baseball-mcp --yes >/dev/null 2>&1; then
      warn "Could not configure $name for $target. Check the linked project and account permissions privately."
      exit 1
    fi
  fi
  say "Configured $name for $target."
}
clerk_stage() {
  local target="$1" prefix="$2"
  open_url "https://dashboard.clerk.com/"
  step "Select the ${target} instance. Use the free Hobby plan and restricted/invitation-only signup."
  step "Enable email verification codes; disable passwords, phone/social sign-in and email links."
  step "For production, set baseball.jamesteuscher.click as the application domain and apply Clerk's exact DNS verification records."
  step "API keys: copy the publishable and secret keys. Only the secret entry is hidden."
  ask "${prefix}_CLERK_PUBLISHABLE_KEY" "Publishable key:"
  ask_secret "${prefix}_CLERK_SECRET_KEY" "Secret key (hidden):"
  ask "${prefix}_CLERK_ISSUER" "Frontend API origin, https://... without a trailing slash:"
  local public_name="${prefix}_CLERK_PUBLISHABLE_KEY" secret_name="${prefix}_CLERK_SECRET_KEY" issuer_name="${prefix}_CLERK_ISSUER"
  write_env "$public_name" "${!public_name}"
  write_env "$secret_name" "${!secret_name}"
  write_env "$issuer_name" "${!issuer_name}"
  put_vercel CLERK_PUBLISHABLE_KEY "${!public_name}" "$target" config
  put_vercel CLERK_SECRET_KEY "${!secret_name}" "$target" secret
  put_vercel CLERK_ISSUER "${!issuer_name}" "$target" config
  step 'Invite approved users. After acceptance, set their PRIVATE metadata to {"baseball_access": true} in the Users dashboard.'
  step "Removing that flag or deleting the user removes question access on the next request."
  pause "Confirm invite-only email-code settings and dashboard approval are configured, then press Enter."
}

banner "Baseball hosted account setup"
say "Secrets are saved only to an ignored private file and provider secret settings. Do not paste them into chat."

stage "Clerk development instance for controlled previews"
clerk_stage preview PREVIEW

stage "Clerk production instance for invited users"
clerk_stage production PRODUCTION
put_vercel PUBLIC_ORIGIN https://baseball.jamesteuscher.click production config

stage "Separate free Neon operational databases"
open_url "https://console.neon.tech/"
step "Create/select a free project. Create separate production and preview databases/roles; do not enable a paid plan or upgrades."
step "Open Connect for each database. Copy pooled PostgreSQL URLs with TLS; use sslmode=verify-full."
ask_secret PRODUCTION_DATABASE_URL "Production database URL (hidden):"
ask_secret PREVIEW_DATABASE_URL "Preview database URL (hidden):"
[[ "$PRODUCTION_DATABASE_URL" != "$PREVIEW_DATABASE_URL" ]] || { warn "Use separate database credentials for preview and production."; exit 1; }
write_env PRODUCTION_DATABASE_URL "$PRODUCTION_DATABASE_URL"
write_env PREVIEW_DATABASE_URL "$PREVIEW_DATABASE_URL"
put_vercel DATABASE_URL "$PRODUCTION_DATABASE_URL" production secret
put_vercel DATABASE_URL "$PREVIEW_DATABASE_URL" preview secret

stage "Dedicated production model credential"
open_url "https://platform.openai.com/api-keys"
step "Select a dedicated project using standard/global processing for this application and create a server-only key. Never add this key to preview/development settings."
step "Check the selected model and the validated pricing profile in config.hosted.json before enabling paid requests."
ask_secret PRODUCTION_OPENAI_API_KEY "Production OpenAI key (hidden):"
write_env PRODUCTION_OPENAI_API_KEY "$PRODUCTION_OPENAI_API_KEY"
put_vercel OPENAI_API_KEY "$PRODUCTION_OPENAI_API_KEY" production secret

stage "Private CI deployment token"
open_url "https://vercel.com/account/tokens"
step "Create a token scoped to jtoosh's Hobby team. It will be stored as the GitHub repository secret VERCEL_TOKEN."
ask_secret VERCEL_TOKEN "Vercel deployment token (hidden):"
write_env VERCEL_TOKEN "$VERCEL_TOKEN"
set_secret VERCEL_TOKEN "$VERCEL_TOKEN"
set_var VERCEL_ORG_ID team_iaNHaeg8ThDFHSVXutJJ5mHj
set_var VERCEL_PROJECT_ID prj_IcWxP3UnxqbqcLUbpJipCrqxHgyg
step "Keep HOSTING_DEPLOY_ENABLED=false until account configuration and the deployment smoke checks in docs/hosting/setup.md are complete."

stage "Custom subdomain DNS and verification"
open_url "https://www.spaceship.com/"
step "Open jamesteuscher.click DNS records. Preserve the apex and unrelated records."
step "Recheck the current project recommendation: npx vercel domains verify baseball.jamesteuscher.click --scope jtooshs-projects"
step "The current recommendation is CNAME name baseball → ae774825b448a93a.vercel-dns-017.com. Apply only the subdomain and Clerk verification records."
confirm "Have you applied the exact current DNS records and completed the owner setup?" || exit 1
npx --yes vercel@63.1.2 domains verify baseball.jamesteuscher.click --scope jtooshs-projects
note "Next: follow docs/hosting/setup.md to smoke-test protected previews, then enable main deployments."
finish
